import{_ as a,c as e,o as s,a2 as i}from"./chunks/framework.D30IVGRC.js";const u=JSON.parse('{"title":"Git Commit 规范详解","description":"","frontmatter":{},"headers":[],"relativePath":"docs/git-commit.md","filePath":"docs/git-commit.md","lastUpdated":1748787318000}'),n={name:"docs/git-commit.md"};function d(l,t,r,o,p,c){return s(),e("div",null,t[0]||(t[0]=[i(`<h1 id="git-commit-规范详解" tabindex="-1">Git Commit 规范详解 <a class="header-anchor" href="#git-commit-规范详解" aria-label="Permalink to &quot;Git Commit 规范详解&quot;">​</a></h1><h2 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h2><p>本项目采用增强版的 Git Commit 规范，基于 <code>commitlint</code> 和 <code>cz-git</code> 实现。这套规范不仅使提交记录更加规范，还便于自动化生成更新日志、版本控制等。</p><h2 id="配置详情" tabindex="-1">配置详情 <a class="header-anchor" href="#配置详情" aria-label="Permalink to &quot;配置详情&quot;">​</a></h2><p>我们在项目根目录下提供了 <code>.commitlintrc.js</code> 配置文件，包含以下主要部分：</p><ol><li>提交类型（type）定义</li><li>作用域（scope）定义</li><li>校验规则（rules）配置</li><li>交互式提交体验（prompt）配置</li></ol><h2 id="提交类型列表" tabindex="-1">提交类型列表 <a class="header-anchor" href="#提交类型列表" aria-label="Permalink to &quot;提交类型列表&quot;">​</a></h2><p>我们定义了以下提交类型：</p><h3 id="标准类型" tabindex="-1">标准类型 <a class="header-anchor" href="#标准类型" aria-label="Permalink to &quot;标准类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>表情符号</th><th>说明</th><th>描述</th></tr></thead><tbody><tr><td>feat</td><td>✨</td><td>新功能</td><td>新增功能 | A new feature</td></tr><tr><td>fix</td><td>🐛</td><td>修复缺陷</td><td>修复Bug | A bug fix</td></tr><tr><td>docs</td><td>📚</td><td>文档更新</td><td>文档更新 | Documentation only changes</td></tr><tr><td>style</td><td>💎</td><td>代码格式</td><td>代码风格调整（不影响代码功能）| Changes that do not affect the meaning of the code</td></tr><tr><td>refactor</td><td>📦</td><td>代码重构</td><td>代码重构（不包括 bug 修复或功能新增）| A code change that neither fixes a bug nor adds a feature</td></tr><tr><td>perf</td><td>🚀</td><td>性能优化</td><td>性能提升 | A code change that improves performance</td></tr><tr><td>test</td><td>🚨</td><td>测试相关</td><td>测试相关 | Adding missing tests or correcting existing tests</td></tr><tr><td>build</td><td>🛠</td><td>构建相关</td><td>构建系统或外部依赖更改 | Changes that affect the build system or external dependencies</td></tr><tr><td>ci</td><td>⚙️</td><td>持续集成</td><td>CI配置更改 | Changes to our CI configuration files and scripts</td></tr><tr><td>chore</td><td>♻️</td><td>其他修改</td><td>其他改动（不修改src或测试文件）| Other changes that do not modify src or test files</td></tr><tr><td>revert</td><td>🗑</td><td>回退代码</td><td>回滚之前的提交 | Revert to a commit</td></tr></tbody></table><h3 id="扩展类型" tabindex="-1">扩展类型 <a class="header-anchor" href="#扩展类型" aria-label="Permalink to &quot;扩展类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>表情符号</th><th>说明</th><th>描述</th></tr></thead><tbody><tr><td>ui</td><td>🎨</td><td>UI相关更改</td><td>用户界面相关更改</td></tr><tr><td>wip</td><td>🚧</td><td>开发中的工作</td><td>开发中的工作（Work In Progress）</td></tr><tr><td>api</td><td>🔌</td><td>API相关更改</td><td>API接口相关变更</td></tr><tr><td>release</td><td>-</td><td>版本发布</td><td>版本发布相关</td></tr><tr><td>deploy</td><td>-</td><td>部署相关</td><td>部署流程或环境相关</td></tr><tr><td>config</td><td>-</td><td>配置调整</td><td>配置文件调整</td></tr><tr><td>i18n</td><td>🌐</td><td>国际化相关</td><td>国际化与本地化相关更改</td></tr><tr><td>lint</td><td>-</td><td>代码检查调整</td><td>代码检查规则调整</td></tr><tr><td>types</td><td>-</td><td>类型定义文件更改</td><td>TypeScript类型定义文件更改</td></tr></tbody></table><h2 id="作用域列表" tabindex="-1">作用域列表 <a class="header-anchor" href="#作用域列表" aria-label="Permalink to &quot;作用域列表&quot;">​</a></h2><p>作用域用于说明提交影响的范围，我们预定义了以下作用域：</p><ul><li>components：组件</li><li>utils：工具</li><li>styles：样式</li><li>deps：依赖</li><li>config：配置</li><li>core：核心功能</li><li>ci：持续集成</li><li>scripts：脚本</li><li>docs：文档</li><li>release：发布</li><li>other：其他</li></ul><p>此外，配置中也允许使用自定义作用域。</p><h2 id="提交信息格式" tabindex="-1">提交信息格式 <a class="header-anchor" href="#提交信息格式" aria-label="Permalink to &quot;提交信息格式&quot;">​</a></h2><p>标准的提交信息格式如下：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;类型&gt;[可选 作用域]: &lt;描述&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[可选 正文]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[可选 脚注]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>例如：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>feat(components): 添加Button组件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>实现了一个可复用的Button组件，支持多种样式和大小。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BREAKING CHANGE: 替换了原有的ButtonBase组件</span></span>
<span class="line"><span>Closes #123</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="交互式提交" tabindex="-1">交互式提交 <a class="header-anchor" href="#交互式提交" aria-label="Permalink to &quot;交互式提交&quot;">​</a></h2><p>使用以下命令可以启动交互式提交：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cz</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cz</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>按照提示回答问题，系统会自动生成符合规范的提交信息。</p><h2 id="特殊功能" tabindex="-1">特殊功能 <a class="header-anchor" href="#特殊功能" aria-label="Permalink to &quot;特殊功能&quot;">​</a></h2><ol><li><p><strong>别名</strong>：提供了快捷别名，如 <code>fd</code> 对应 <code>docs: fix typos</code></p></li><li><p><strong>Issue前缀</strong>：支持GitEE工作流</p><ul><li><code>link</code>: 链接 ISSUES 进行中</li><li><code>closed</code>: 标记 ISSUES 已完成</li></ul></li><li><p><strong>破坏性变更</strong>：可以在提交中明确标注破坏性变更</p></li></ol><h2 id="提交信息的好处" tabindex="-1">提交信息的好处 <a class="header-anchor" href="#提交信息的好处" aria-label="Permalink to &quot;提交信息的好处&quot;">​</a></h2><ul><li><strong>自动化更新日志</strong>：规范的提交信息可以自动生成更新日志</li><li><strong>版本控制</strong>：便于语义化版本控制</li><li><strong>代码审查</strong>：提高代码审查效率</li><li><strong>项目历史</strong>：提供清晰的项目历史记录</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ol><li><strong>保持简洁</strong>：提交描述应该简洁明了</li><li><strong>聚焦单一变更</strong>：每次提交应该专注于单一变更</li><li><strong>使用现在时态</strong>：使用&quot;add&quot;而不是&quot;added&quot;</li><li><strong>不使用句号结尾</strong>：描述不要以句号结尾</li><li><strong>详细说明重大变更</strong>：对于破坏性变更，详细说明原因和迁移方法</li><li><strong>相关链接</strong>：需要时添加相关的Issue或PR链接</li></ol><h2 id="常见错误" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误" aria-label="Permalink to &quot;常见错误&quot;">​</a></h2><ul><li>提交信息过于模糊，如&quot;修复bug&quot;</li><li>混合多个不相关的变更</li><li>忽略提交类型和作用域</li><li>提交过大的变更</li></ul><h2 id="校验规则" tabindex="-1">校验规则 <a class="header-anchor" href="#校验规则" aria-label="Permalink to &quot;校验规则&quot;">​</a></h2><p>项目使用 <code>commitlint</code> 工具校验提交信息，不符合规范的提交将被拒绝。主要校验规则包括：</p><ul><li>type必须在预定义列表中</li><li>type必须小写</li><li>type不能为空</li><li>scope必须在预定义列表中（可自定义）</li><li>scope必须小写</li><li>subject不能为空</li><li>subject不能以.结尾</li><li>header长度不超过100个字符</li></ul><h2 id="更多资源" tabindex="-1">更多资源 <a class="header-anchor" href="#更多资源" aria-label="Permalink to &quot;更多资源&quot;">​</a></h2><ul><li><a href="https://www.conventionalcommits.org/" target="_blank" rel="noreferrer">Conventional Commits</a></li><li><a href="https://cz-git.qbb.sh/zh/" target="_blank" rel="noreferrer">cz-git 文档</a></li><li><a href="https://commitlint.js.org/" target="_blank" rel="noreferrer">commitlint 文档</a></li></ul>`,38)]))}const b=a(n,[["render",d]]);export{u as __pageData,b as default};
